1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Numeric membership level for pet owners, from 1 to 4, derived from an owner's
7	 * {@link MembershipPoints}. The points are banded into a level: 1 for 0-1 points, 2 for 2-3 points,
8	 * 3 for 4-5 points and 4 for 6 or more points. Because a newly created owner earns no tenure points,
9	 * a new owner tops out at 5 points (email, unique name and a household of 3 or more), reaching level
10	 * 4 only once at least one fiscal year has elapsed. Used by the owner mapper to expose {@code membershipLevel}
11	 * on responses.
12	 *
13	 * <p>A new owner's level is additionally capped at creation time so it cannot exceed one above the
14	 * maximum level then held by its household members (see {@link CapMembershipLevel}); the ceiling is
15	 * stored on the owner as {@code membershipLevelCap}. {@link #of(Owner)} applies that ceiling to the
16	 * points-banded level. With no ceiling recorded (no existing household member, or a pre-existing
17	 * owner) the level is the points-banded value unchanged.
18	 */
19	public final class MembershipLevel {
20	
21	    private MembershipLevel() {
22	    }
23	
24	    /**
25	     * The membership level for the given points total: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or
26	     * more.
27	     */
28	    public static int of(int points) {
29	        if (points <= 1) {
30	            return 1;
31	        }
32	        if (points <= 3) {
33	            return 2;
34	        }
35	        if (points <= 5) {
36	            return 3;
37	        }
38	        return 4;
39	    }
40	
41	    /**
42	     * The owner's effective membership level: the points-banded level ({@link #of(int)} over
43	     * {@link MembershipPoints}), lowered to the stored {@code membershipLevelCap} ceiling when one
44	     * was recorded at create time. With no ceiling the points-banded level is returned unchanged.
45	     */
46	    public static int of(Owner owner) {
47	        int level = of(MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(),
48	                owner.getHouseholdSize(), owner.getRegistrationDate()));
49	        Integer cap = owner.getMembershipLevelCap();
50	        return cap == null ? level : Math.min(level, cap);
51	    }
52	}
