1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Membership number for pet owners, formatted {@code <customerCode>-M<YY>} where YY is the last two
7	 * digits of the registration date's fiscal year (the fiscal year starting 1 July, named by the
8	 * calendar year it ends in — see {@link FiscalYear}), e.g. {@code NSW-1A2B3C4D-M27} for a July-2026
9	 * registration. Derived purely from the owner's own {@code customerCode} and {@code registrationDate},
10	 * so it carries no stored state and is seed-independent. Used by the owner mapper to expose
11	 * {@code membershipNumber} on responses.
12	 */
13	public final class MembershipNumber {
14	
15	    private MembershipNumber() {
16	    }
17	
18	    /**
19	     * The membership number for the given customer code and registration date, or {@code null} when
20	     * either input is absent (e.g. legacy owners with no customer code or registration date).
21	     */
22	    public static String of(String customerCode, LocalDate registrationDate) {
23	        if (customerCode == null || registrationDate == null) {
24	            return null;
25	        }
26	        return String.format("%s-M%02d", customerCode, FiscalYear.of(registrationDate) % 100);
27	    }
28	}
