7	/**
8	 * Step of {@code POST /api/owners} that records the owner's membership-level ceiling: a new owner's
9	 * {@code membershipLevel} cannot exceed one above the current maximum {@code membershipLevel} among
10	 * its household members ({@link Household#id(String, String) same householdId}, i.e. same last name
11	 * and postcode). Runs after {@link CountHouseholdMembers} (so the household state is set) and before
12	 * {@link SaveOwner} (so the owner being created is not counted as its own household member). The
13	 * ceiling is {@code maxHouseholdMemberLevel + 1}, stored on the owner as {@code membershipLevelCap}
14	 * and applied by {@link MembershipLevel#of(Owner)} when the level is exposed. With no existing
15	 * household member no ceiling is recorded and no cap applies.
16	 */
17	public class CapMembershipLevel {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String householdId = Household.id(owner.getLastName(), owner.getPostcode());
21	        Integer maxLevel = null;
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (householdId.equals(Household.id(other.getLastName(), other.getPostcode()))) {
24	                int level = MembershipLevel.of(other);
25	                if (maxLevel == null || level > maxLevel) {
26	                    maxLevel = level;
27	                }
28	            }
29	        }
30	        if (maxLevel != null) {
31	            owner.setMembershipLevelCap(maxLevel + 1);
32	        }
33	    }
34	}
