1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.server.http.HttpHeader;
5	import net.officefloor.server.http.ServerHttpConnection;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	
12	/**
13	 * First step of {@code POST /api/owners}. Honours an optional {@code Idempotency-Key} header: when
14	 * the request repeats a key already recorded by {@link RecordIdempotency}, the originally created
15	 * owner is returned with 200 and the create pipeline is short-circuited, so no duplicate is created
16	 * (and the usual identity-conflict 409 is never reached). Otherwise — no key, or a key not seen
17	 * before — the {@code create} flow is taken to run the normal validate/build/save pipeline.
18	 */
19	public class CheckIdempotency {
20	
21	    /** Header naming the idempotency key; absent means a normal (non-idempotent) create. */
22	    static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
23	
24	    @FunctionalInterface
25	    public interface CreateFlow {
26	        void create();
27	    }
28	
29	    public void service(ServerHttpConnection connection, IdempotencyStore idempotencyStore,
30	            OwnerRepository ownerRepository, OwnerMapper ownerMapper, ObjectResponse<OwnerDto> response,
31	            @Flow("create") CreateFlow createFlow) {
32	        String key = idempotencyKey(connection);
33	        if (key != null) {
34	            Integer existingId = idempotencyStore.get(key);
35	            if (existingId != null) {
36	                Owner existing = ownerRepository.findById(existingId);
37	                if (existing != null) {
38	                    response.send(ownerMapper.toOwnerDto(existing)); // 200, no duplicate created
39	                    return; // short-circuit: do not take the create flow
40	                }
41	            }
42	        }
43	        createFlow.create();
44	    }
45	
46	    /** The trimmed {@code Idempotency-Key} header value, or {@code null} when absent or blank. */
47	    static String idempotencyKey(ServerHttpConnection connection) {
48	        HttpHeader header = connection.getRequest().getHeaders().getHeader(IDEMPOTENCY_KEY_HEADER);
49	        if (header == null) {
50	            return null;
51	        }
52	        String value = header.getValue();
53	        if (value == null || value.isBlank()) {
54	            return null;
55	        }
56	        return value.trim();
57	    }
58	}
