4	import net.officefloor.server.http.ServerHttpConnection;
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Records the {@code Idempotency-Key} (when the request carried one) against the just-created
9	 * owner's id, so a later repeat of the same key returns this owner instead of creating a duplicate
10	 * (see {@link CheckIdempotency}).
11	 *
12	 * <p>Runs after {@link SaveOwner}, so the owner already has its generated id, and only on the create
13	 * path — a repeat is short-circuited before it reaches here.
14	 */
15	public class RecordIdempotency {
16	
17	    public void service(ServerHttpConnection connection, @Val Owner owner,
18	            IdempotencyStore idempotencyStore) {
19	        String key = CheckIdempotency.idempotencyKey(connection);
20	        if (key != null) {
21	            idempotencyStore.record(key, owner.getId());
22	        }
23	    }
24	}
